#include "../../../native/translation_output.hpp"
#include "../../../native/llm_batch.hpp"
int main(){try{size_t count=0;auto check=[&](bool value){require(value,"Translation output check "+std::to_string(++count)+" failed");};
 check(!translation_output::valid("예의나作法 같은 거 말이야.","Korean"));check(!translation_output::valid("예의나作법이라는 게 말이야.","Korean"));check(translation_output::valid("예의나 작법 같은 거 말이야.","Korean"));check(!translation_output::valid("치치하ルの 평화","Korean"));
 for(const auto& value:{"예의가...","너무 없네","오","GO!!","40 km/h","!? ...","A + B = 3","ABC-12","🥊"})check(translation_output::valid(value,"Korean"));
 check(translation_output::valid("礼儀や作法。","Japanese"));check(translation_output::valid("礼仪和礼节。","Chinese"));check(!translation_output::valid("礼儀や作法。","Chinese"));check(!translation_output::valid("예의와礼节","Chinese"));check(!translation_output::valid("예의と作法","Japanese"));check(translation_output::valid("Good manners.","English"));check(!translation_output::valid("Good 作法.","English"));check(!translation_output::valid("Good 예의.","English"));
 const json approved=json::array({{{"required","作法"}}});check(translation_output::valid("예의와 作法.","Korean",approved));check(!translation_output::valid("예의와 作法や礼儀.","Korean",approved));check(translation_output::pattern("Korean",approved).empty());check(!translation_output::pattern("Korean",json::array({{{"required","치치하얼"}}})).empty());
 check(!translation_output::valid(json::parse("\"\\u4f5c\\u6cd5\""),"Korean"));check(!translation_output::valid("𠀀","Korean"));check(!translation_output::valid("ｻﾎｳ","English"));check(!translation_output::valid("ㇰ","Korean"));check(!translation_output::valid("ㄱ","English"));check(translation_output::valid("Português déjà vu","English"));check(translation_output::valid("Новое имя","Russian"));check(translation_output::pattern("Russian").empty());
 check(translation_output::effect({{"type","effect"},{"text","オ"}}));check(!translation_output::effect({{"type","text"},{"text","Dialogue"}}));check(!translation_output::effect({{"text","Legacy"}}));check(!translation_output::effect({{"type","effect"},{"textVerification",{{"role","DIALOGUE"}}}}));check(!translation_output::effect({{"type","effect"},{"textVerification",{{"role","LABEL"}}}}));check(translation_output::effect({{"type","effect"},{"textVerification",{{"role","UNCERTAIN"}}}}));
 const json original={{{"id",1},{"type","effect"},{"text","オ"}},{{"id",2},{"type","text"},{"text","お行儀が・・・・"}},{{"id",3},{"type","effect"},{"text","オ"}},{{"id",6},{"type","text"},{"text","悪すぎるね"}}};const auto unchanged=original.dump();std::array<json,2> groups{json::array(),json::array()};for(const auto& r:original)groups[translation_output::effect(r)].push_back({{"id",std::to_string(r.at("id").get<int>())},{"text",r.at("text")}});check(groups[0].size()==2&&groups[1].size()==2);const LlmBatch dialogue(groups[0]),effects(groups[1]);check(dialogue.original_ids.at("row_000000")=="2");check(effects.original_ids.at("row_000000")=="1");check(dialogue.restore({{"row_000000","예의가..."},{"row_000001","너무 없네"}}).at("6")=="너무 없네");check(effects.restore({{"row_000000","오"},{"row_000001","오"}}).at("3")=="오");check(original.dump()==unchanged);
 std::cout<<json({{"ok",true},{"checks",count},{"targetLanguages",4},{"explicitDictionaryExemption",true},{"schemaEscapeRechecked",true},{"independentGroupIds",true},{"sourceUnchanged",true}}).dump()<<std::endl;
 }catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
